def transform(grid):
    """Repair each locally closed 5-outline: fill interior with 8, mark two-gap notches 7."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # For every axis-aligned rectangle whose boundary is all 5, fill its interior.
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    if (all(grid[r0][c] == 5 for c in range(c0, c1+1)) and
                        all(grid[r1][c] == 5 for c in range(c0, c1+1)) and
                        all(grid[r][c0] == 5 for r in range(r0, r1+1)) and
                        all(grid[r][c1] == 5 for r in range(r0, r1+1))):
                        for r in range(r0+1, r1):
                            for c in range(c0+1, c1):
                                if grid[r][c] == 0:
                                    out[r][c] = 8
    # Two-cell concavities between a 5 on the left/right become 7 where
    # the missing block continues into a neighboring row, as in examples.
    for r in range(h):
        for c in range(w-3):
            if grid[r][c:c+4] == [5,0,0,5]:
                # Restrict marking to gaps that form a corner of a multi-row object.
                down = r+1 < h and (grid[r+1][c+1] == 0 or grid[r+1][c+2] == 0)
                up = r > 0 and (grid[r-1][c+1] == 0 or grid[r-1][c+2] == 0)
                if down or up:
                    out[r][c+1] = out[r][c+2] = 7
    return out
